const q = $json.query ?? {};
if (!q.job_id || !/^[A-Za-z0-9._:-]{1,128}$/.test(q.job_id)) throw new Error('valid job_id is required');
return [{ json: { job_id: q.job_id } }];

const s = $json;
if (s.status !== 'completed') return [{ json: s }];
const result = s.result ?? {};
const ranked = [...(result.results ?? [])].sort((a,b) => (b.curator_score ?? b.relevance_score ?? 0) - (a.curator_score ?? a.relevance_score ?? 0));
return [{ json: { ok: true, job_id: s.job_id, status: s.status, query: result.query, generated_at: result.generated_at, recommendations: ranked.slice(0,5).map((x,i) => ({ rank: i+1, title: x.title, url: x.url, source: x.source, published_at: x.published_at, curator_score: x.curator_score, topic_relevance_score: x.topic_relevance_score, topic_anchor_score: x.topic_anchor_score, personal_relevance_score: x.personal_relevance_score, recommendation_reason: x.recommendation_reason, summary: x.summary })) } }];
